_id AND ap.role IN ('owner','super_admin')\n          )\n        )\n    ),\n    FALSE\n  );\n$function$\n","present":true,"proconfig":["search_path=pg_catalog, public, api, internal, pg_temp"],"prokind":"f","prosrc_md5_lf":"20432397b8b7ba6af249553b14ce37af","returns":"boolean","schema":"internal","security_definer":true,"service_execute":true,"set_returning":false,"strict":false,"volatility":"s"},{"acl":["postgres=X/postgres","service_role=X/postgres"],"anon_execute":false,"argument_count":3,"arguments":"p_user_id uuid, p_org_object_id text, p_event text","authenticated_execute":false,"default_count":0,"definition_md5_lf":"348fae43963d3ec07d489aa80f0654a4","identity_arguments":"p_user_id uuid, p_org_object_id text, p_event text","kind":"new","language":"plpgsql","leakproof":false,"name":"measure_list_email","owner":"postgres","parallel":"u","prerequisite_definition":null,"present":true,"proconfig":["search_path=pg_catalog, pg_temp"],"prokind":"f","prosrc_md5_lf":"9f445ceec0c3ecf01fb9ee3e89b3701c","returns":"void","schema":"internal","security_definer":false,"service_execute":true,"set_returning":false,"strict":false,"volatility":"v"}],"ledger":{"count":192,"fingerprint":"0161976feebf0759ee6c9defc57efdda","fingerprint_algorithm":"ledger-v1-md5","smtp_named_receipts":[]},"membership_grants":[{"admin_option":false,"grantor":"supabase_admin","inherit_option":false,"member":"authenticator","role":"anon","set_option":true,"subject":"postgres"},{"admin_option":false,"grantor":"supabase_admin","inherit_option":false,"member":"authenticator","role":"authenticated","set_option":true,"subject":"postgres"},{"admin_option":false,"grantor":"supabase_admin","inherit_option":false,"member":"authenticator","role":"service_role","set_option":true,"subject":"postgres"},{"admin_option":false,"grantor":"supabase_admin","inherit_option":true,"member":"pg_monitor","role":"pg_read_all_settings","set_option":true,"subject":"postgres"},{"admin_option":false,"grantor":"supabase_admin","inheri